const itemsDetails = await browserjs(tabId, () => {
  const results = [];
  const items = document.querySelectorAll('ol.sku-list > li, .sku-item, [data-sku-id]');

  // Also find all product cards by looking for the titles
  const headings = Array.from(document.querySelectorAll('h3')).filter(h => h.textContent.includes('Samsung'));

  for (const h of headings) {
    const card = h.closest('li') || h.parentElement;
    const titleLink = h.closest('a') || card.querySelector('a');
    const href = titleLink?.href;
    const title = h.textContent.trim().replace(/\s+/g, ' ');

    // Find prices and open box details
    const textContent = card.innerText || card.textContent;

    // Look for open-box specific text
    const openBoxMatches = Array.from(card.querySelectorAll('*'))
      .filter(el => el.children.length === 0 && (el.textContent.includes('Open-box') || el.textContent.includes('Open-Box') || el.textContent.includes('$')))
      .map(el => el.textContent.trim());

    results.push({
      title,
      href,
      cardText: textContent.replace(/\s+/g, ' ').slice(0, 500),
      openBoxMatches: Array.from(new Set(openBoxMatches))
    });
  }
  return results;
});

